const summaryRaw   = $('Fetch Vercel Summary').item.json;
const pagesRaw     = $('Fetch Vercel Top Pages').item.json;
const referrersRaw = $('Fetch Vercel Referrers').item.json;

// visits/count → { data: { pageviews, visitors } }
const s = summaryRaw.data || {};
const pageViews = s.pageviews || 0;
const visitors  = s.visitors  || 0;
const pagesPerVisit = visitors > 0 ? (pageViews / visitors).toFixed(2) : '0.00';

// visits/aggregate by=requestPath → { data: [{ requestPath, pageviews, visitors }] }
const pagesArr = Array.isArray(pagesRaw.data) ? pagesRaw.data : [];
const topPages = pagesArr.slice(0, 5).map(p => ({
  page:     p.requestPath || 'Unknown',
  views:    p.pageviews || 0,
  visitors: p.visitors  || 0
}));

// visits/aggregate by=referrerHostname → { data: [{ referrerHostname, pageviews, visitors }] }
const refArr = Array.isArray(referrersRaw.data) ? referrersRaw.data : [];
const referrers = refArr.slice(0, 5).map(r => ({
  source: r.referrerHostname || 'Direct / None',
  visits: r.visitors || r.pageviews || 0
}));

const reportData = JSON.stringify({
  period: 'Last 7 days',
  overview: { pageViews, visitors, pagesPerVisit },
  topPages,
  referrers
}, null, 2);

return [{ json: { reportData } }];

// Runs only when the AI call fails — builds a plain-stats email body
// with the same HTML styling and the same `output` field the email node reads.
const report = JSON.parse($('Build Report').first().json.reportData);
const o = report.overview || {};

const pageRows = (report.topPages || [])
  .map(p => `<li><strong>${p.page}</strong> — ${p.views} views (${p.visitors} visitors)</li>`)
  .join('');
const refRows = (report.referrers || [])
  .map(r => `<li><strong>${r.source}</strong> — ${r.visits} visits</li>`)
  .join('');

const output = `
<p style="margin:0 0 12px;">The AI summary was unavailable this week, so here are your raw numbers.</p>
<h3 style="color:#1a73c8;margin:20px 0 8px;">📈 Key Metrics</h3>
<ul style="margin:0 0 12px;padding-left:20px;">
  <li>Page views: <strong>${o.pageViews ?? 0}</strong></li>
  <li>Unique visitors: <strong>${o.visitors ?? 0}</strong></li>
  <li>Pages per visit: <strong>${o.pagesPerVisit ?? '0.00'}</strong></li>
</ul>
<h3 style="color:#1a73c8;margin:20px 0 8px;">🔝 Top Pages</h3>
<ul style="margin:0 0 12px;padding-left:20px;">${pageRows || '<li>No data this week</li>'}</ul>
<h3 style="color:#1a73c8;margin:20px 0 8px;">🚦 Traffic Sources</h3>
<ul style="margin:0 0 12px;padding-left:20px;">${refRows || '<li>No data this week</li>'}</ul>`;

return [{ json: { output } }];
